ALTER TABLE gbdp.gold_gbdp.fact_game ALTER COLUMN `venue` COMMENT 'Venue name (MLB, KBO, Retrosheet); null elsewhere.';

ALTER TABLE gbdp.gold_gbdp.fact_game ALTER COLUMN `game_type` COMMENT 'The source\'s game type. MLB Stats API gameType (R regular season, S spring, E exhibition, A All-Star, F wild card, D division series, L LCS, W World Series); NPB SPAIA\'s Japanese name (セ・リーグ公式戦 / パ・リーグ公式戦 league games, セ・パ交流戦 interleague, クライマックスシリーズ, 日本シリーズ); Retrosheet\'s gametype as the statsapi codes (tie-breaker playoff games R, P its pre-1950 championship series); kbo_api R/E/A from its series code and P for every postseason round. indy/kbo/lmb local files pass a game_type through when they have one, else null. Null too in partitions published before gold had the column. See vocabularies.season_phase.';

