ALTER TABLE gbdp.gold_gbdp.fact_game ALTER COLUMN `source` COMMENT 'Source system.';

ALTER TABLE gbdp.gold_gbdp.fact_game ALTER COLUMN `source_game_id` COMMENT 'The source\'s own game ID (MLB gamePk, SPAIA gameId, KBO G_ID, Retrosheet gid).';

ALTER TABLE gbdp.gold_gbdp.fact_game ALTER COLUMN `dt` COMMENT 'Schedule date the row was fetched for.';

ALTER TABLE gbdp.gold_gbdp.fact_game ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

