COMMENT ON TABLE gbdp.gold_gbdp.fact_plate_appearance IS 'One row per plate appearance: MLB from Statcast (pitch rows grouped by at-bat), NPB rebuilt from SPAIA\'s text play-by-play (one row per real PA), and Retrosheet plays where loaded. Plus TRUNCATED rows, which are not plate appearances (see vocabularies.event_type). Grain: one row per pa_id. Sources: mlb_statcast, npb_spaia, retrosheet_local. Caveat: TRUNCATED rows are not plate appearances. Exclude them from PA counts and every PA-based rate (use the is_pa flag in v_plate_appearance); keep them for runs and outs. Caveat: For Statcast the state after a PA is read from the next PA\'s first pitch, so a stolen base or pickoff between PAs is credited to the earlier PA. Caveat: MLB games can be in both mlb_statcast and retrosheet_local; filter on source to avoid counting a game twice. Caveat: There is no RBI outside Retrosheet. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `pa_id` COMMENT 'Canonical ID. Statcast and fact_pitch derive it from gamePk and at-bat number.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `game_id` COMMENT 'FK to fact_game.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `inning` COMMENT 'Inning number.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `is_top_inning` COMMENT 'True in the top half (the away team bats).';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `batting_team_id` COMMENT 'FK to dim_team. Retrosheet states it; otherwise filled from fact_game\'s home/away teams and the inning half.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `fielding_team_id` COMMENT 'FK to dim_team, the other team.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `batter_id` COMMENT 'FK to dim_player. For Statcast, the batter on the PA\'s last pitch (a pinch hitter takes over the PA).';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `pitcher_id` COMMENT 'FK to dim_player. Null for NPB (the text play-by-play doesn\'t name the pitcher per PA).';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `event_type` COMMENT 'The outcome, see vocabularies.event_type.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `rbi` COMMENT 'Runs batted in. Retrosheet only; null for Statcast and NPB.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `runs_scored_on_play` COMMENT 'Runs the batting team scored during the PA, every source including NPB (from the score SPAIA prints). For Statcast, measured from the PA\'s first pitch to its last, so runs on a wild pitch or steal during the PA count.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `outs_on_play` COMMENT 'outs_after - outs_before, so it includes outs made on the bases during the PA.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `base_state_before` COMMENT 'Runners on base before the PA, see vocabularies.base_state.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `outs_before` COMMENT 'Outs before the PA (0-2).';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `base_state_after` COMMENT 'Runners after the PA; 0 when it ended the half-inning; null (unknown) when it ended the game short of three outs, a walk-off, in every source. For NPB, the runners come from the next PA\'s header, or for a half-inning\'s last PA from the end of its result text, and are null when that text names no runners.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `outs_after` COMMENT 'Outs after the PA (0-3).';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `runs_to_end_of_inning` COMMENT 'Runs from this PA through the end of its half-inning, what run expectancy averages. Null when the half-inning never reached three outs (walk-off, suspended, gaps in the feed) or a later PA\'s runs are unknown.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `source` COMMENT 'Source system.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.fact_plate_appearance ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.fact_boxscore_batting IS 'Per-player, per-game batting line from each source\'s box score. Grain: one row per (game_id, player_id, source). Sources: mlb_statsapi, kbo_api, indy_local, kbo_local, lmb_local, retrosheet_local. Caveat: There is no NPB box score in gold; NPB batting comes from fact_plate_appearance. Caveat: kbo_api fills only ab, h, rbi and r. Caveat: The local sources (indy_local, kbo_local, lmb_local, retrosheet_local) only have rows where manual files were supplied. Caveat: Per game, not per season. SUM over the games you want, or use the metric view mv_batting_box. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `game_id` COMMENT 'FK to fact_game.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `team_id` COMMENT 'FK to dim_team.';

