ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `ab` COMMENT 'At-bats.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `h` COMMENT 'Hits.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `c_2b` COMMENT 'Doubles. c_2b in Unity Catalog. Null for kbo_api.';

