ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `hr` COMMENT 'Home runs. Null for kbo_api.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `bb` COMMENT 'Walks. Null for kbo_api.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `so` COMMENT 'Strikeouts. Null for kbo_api.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `rbi` COMMENT 'Runs batted in.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `r` COMMENT 'Runs scored.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `source` COMMENT 'Source system.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_batting ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.fact_boxscore_pitching IS 'Per-player, per-game pitching line from each source\'s box score. Grain: one row per (game_id, player_id, source). Sources: mlb_statsapi, kbo_api, indy_local, kbo_local, lmb_local, retrosheet_local. Caveat: No NPB box score in gold. Caveat: The local sources only have rows where manual files were supplied. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `game_id` COMMENT 'FK to fact_game.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `team_id` COMMENT 'FK to dim_team.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `player_id` COMMENT 'FK to dim_player. kbo_api pitchers are keyed by team + name (no source ID).';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `ip` COMMENT 'Innings pitched as a STRING, not a decimal. MLB and Retrosheet write "6.1" for 6 1/3 and "6.2" for 6 2/3 innings; kbo_api writes "6", "5 2/3" or "1/3". Never sum or average it as a number: convert to outs first (ip_outs in v_pitching_line does).';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `h` COMMENT 'Hits allowed.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `r` COMMENT 'Runs allowed.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `er` COMMENT 'Earned runs allowed.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `bb` COMMENT 'Walks allowed (kbo_api counts walks plus hit batters, its 4사구 column).';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `so` COMMENT 'Strikeouts.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `hr` COMMENT 'Home runs allowed.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `source` COMMENT 'Source system.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.fact_boxscore_pitching ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.fact_standings IS 'NPB standings as published by SPAIA. No other league has standings; derive records from fact_game (metric view mv_team_games). Grain: one row per team_id per dt. Sources: npb_spaia. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `league_id` COMMENT 'Always NPB. FK to dim_league.league_id.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `season_id` COMMENT 'FK to dim_season.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `team_id` COMMENT 'FK to dim_team.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `w` COMMENT 'Wins.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `l` COMMENT 'Losses.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `t` COMMENT 'Ties.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `pct` COMMENT 'Winning percentage as text (".500").';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `gb` COMMENT 'Games behind as text ("-" for the leader).';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `source` COMMENT 'Always npb_spaia.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `dt` COMMENT 'Standings date.';

ALTER TABLE gbdp.gold_gbdp.fact_standings ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.bridge_source_ids IS 'Identity bridge, written by identity/resolver.py: every (entity_type, source, source_id) seen that day and its canonical ID. Use it to go from a raw source ID (an MLB gamePk player ID you know) to the player_id or team_id used in gold. Grain: one row per sighting of (entity_type, source, source_id) per dt; a team is listed once per game it played that day. Sources: mlb_statsapi, npb_spaia, kbo_api, indy_local, kbo_local, lmb_local, retrosheet_local. Caveat: Not unique on (entity_type, source, source_id, dt). The duplicates carry the same canonical_id, so SELECT DISTINCT entity_type, source, source_id, canonical_id before joining or counting. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `entity_type` COMMENT 'player or team.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `source` COMMENT 'Source system.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `source_id` COMMENT 'The source\'s own ID (for kbo_api players, which have none, team + name, e.g. SS:이승현 and SS:이승현#2).';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `canonical_id` COMMENT 'The player_id or team_id used in gold.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `first_seen_dt` COMMENT 'The dt (identity is resolved one day at a time).';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `last_seen_dt` COMMENT 'The dt.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `confidence` COMMENT 'Match confidence, 0-1 (0.9 for an exact source ID).';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `match_method` COMMENT 'exact_id, exact_name_dob, name_team, exact_name_league or unknown.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `manual_override` COMMENT 'True when manual_entity_links.csv set canonical_id.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `notes` COMMENT 'Always null.';

ALTER TABLE gbdp.gold_gbdp.bridge_source_ids ALTER COLUMN `dt` COMMENT 'Snapshot date.';

COMMENT ON TABLE gbdp.gold_gbdp.run_expectancy IS 'Season-to-date run expectancy (the RE24 matrix) per league: the average runs scored from each base/out state to the end of the half-inning, over every completed half-inning of that league\'s season through dt. The latest dt of a season is the full-season matrix only if every date was published in order: see the caveat. Grain: one row per (league_code, base_state, outs) per dt. Sources: fact_plate_appearance. Caveat: Only half-innings that reached three outs count (runs_to_end_of_inning not null). Caveat: Early in a season the counts are small and the values noisy; check pa_count. Caveat: Each dt is summed from run_expectancy_daily. Publishing a date range now also rebuilds every later date of that season from the daily rows, but a later dt can still be stale if that refresh didn\'t run (an interrupted rebuild, or partitions from before the fix). Summing run_expectancy_daily is always current, and is what mv_run_expectancy and v_plate_appearance\'s run values do. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `league_code` COMMENT 'MLB or NPB (the leagues with plate appearances).';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `league_id` COMMENT 'FK to dim_league.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `season_year` COMMENT 'The dt\'s calendar year; each season starts from zero.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `base_state` COMMENT 'Runners on base, see vocabularies.base_state.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `outs` COMMENT 'Outs, 0-2.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `pa_count` COMMENT 'PAs from this state in the season through dt (TRUNCATED rows included, since they end innings).';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `runs` COMMENT 'Sum of runs_to_end_of_inning over those PAs.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `exp_runs` COMMENT 'runs / pa_count, rounded to 4 places.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `dt` COMMENT 'Through this date.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.run_expectancy_daily IS 'One day\'s contribution to run_expectancy: PA count and rest-of-inning runs per (league, base state, outs). run_expectancy for a date is the sum of these from January 1 through it, as of when that date was published. Sum any date range yourself for the matrix over that range (metric view mv_run_expectancy and v_plate_appearance do); unlike run_expectancy, the sum is never stale after a rebuild. Grain: one row per (league_code, base_state, outs) per dt. Sources: fact_plate_appearance. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `league_code` COMMENT 'MLB or NPB.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `league_id` COMMENT 'FK to dim_league.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `season_year` COMMENT 'The dt\'s calendar year.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `base_state` COMMENT 'Runners on base, see vocabularies.base_state.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `outs` COMMENT 'Outs, 0-2.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `pa_count` COMMENT 'PAs from this state that day with a known runs_to_end_of_inning.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `runs` COMMENT 'Sum of their runs_to_end_of_inning.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.run_expectancy_daily ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.breakout_candidates IS 'The baseline breakout model\'s top batters per league on each dt: the probability that a batter\'s wOBA over the next horizon_days days beats his baseline-window wOBA by the configured margin (the label of ml_breakout_examples), from a logistic regression trained by scripts/train_breakout.py (artifact and settings in configs/ml.yaml). Uses only data through dt. This table used to hold the day\'s top 20 batters by home runs; hr, h and ab keep that meaning (the day\'s totals), now from plate appearances. Grain: up to model.top_n_per_league (25) rows per league per dt. Sources: ml_breakout_examples. Caveat: Empty for a dt when no usable model artifact exists (none trained, or trained on another feature definition); the reason is in the gold_publish log. A dt is never scored with a stand-in. Caveat: The committed model was trained on the 2025 season (MLB Statcast, NPB SPAIA); see model_version and the README for its evaluation. Probabilities are only as calibrated as that season is like this one. Caveat: Partition...';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `player_id` COMMENT 'FK to dim_player.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `league_code` COMMENT 'MLB or NPB.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `season_year` COMMENT 'The dt\'s calendar year.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `hr` COMMENT 'Home runs on dt (from plate appearances; 0 if he didn\'t bat).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `h` COMMENT 'Hits on dt.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `ab` COMMENT 'At-bats on dt.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `score` COMMENT 'Breakout probability over the next horizon_days days, 0-1, rounded to 6 places.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `rank` COMMENT '1 = highest score in the league on dt (ties broken by player_id).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `model_version` COMMENT 'The artifact that scored the row (breakout_logreg-<hash of its coefficients>).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `horizon_days` COMMENT 'Days after dt the prediction covers (configs/ml.yaml breakout.label_days).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `f_base_pa` COMMENT 'PAs in the baseline window ending dt (see ml_breakout_examples).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `f_base_woba` COMMENT 'wOBA in the baseline window ending dt.';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `f_recent_woba` COMMENT 'wOBA in the recent window ending dt (null without a wOBA PA).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `dt` COMMENT 'As-of date (scored with data through this date).';

ALTER TABLE gbdp.gold_gbdp.breakout_candidates ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.feature_player_rolling_30d IS 'Per-player batting totals over the 30 days ending dt, from fact_boxscore_batting, for ML features. Grain: one row per player_id per dt. Sources: fact_boxscore_batting. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `player_id` COMMENT 'FK to dim_player.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `ab` COMMENT 'At-bats in the window.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `h` COMMENT 'Hits in the window.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `hr` COMMENT 'Home runs in the window (0 for kbo_api, which has no HR).';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `rbi` COMMENT 'RBI in the window.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `bb` COMMENT 'Walks in the window.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `so` COMMENT 'Strikeouts in the window.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `window_days` COMMENT 'Always 30.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `dt` COMMENT 'Last day of the window.';

ALTER TABLE gbdp.gold_gbdp.feature_player_rolling_30d ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.feature_pitch_daily IS 'Each MLB pitcher\'s pitches by pitch type per day, from Savant\'s raw Statcast rows in silver (insights/statcast_features.py): counts, swings, whiffs, velocity and spin sums, and the wOBA and xwOBA of the plate appearances that ended on that pitch type. Sums, not rates, so any date range adds up: whiff rate = sum(whiffs) / sum(swings), velocity = sum(velo_sum) / sum(velo_n), xwOBA against = sum(xwoba_value) / sum(woba_den). Feeds the new_pitch and velocity_change insight detectors. Grain: one row per pitcher per pitch type per dt. Sources: mlb_statcast. Caveat: Written by the statcast_features_publish stage (in the nightly), from silver, not by gold_publish. Caveat: xwOBA follows Savant (a ball in play counts estimated_woba_using_speedangle, a walk, HBP or strikeout its woba_value); empty where Savant leaves the estimate blank. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `player_id` COMMENT 'FK to dim_player (the pitcher).';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `pitch_type` COMMENT 'Savant\'s pitch type code (FF four-seam, SI sinker, SL slider, ST sweeper, CH changeup, ...).';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `pitches` COMMENT 'Pitches of this type thrown on dt.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `swings` COMMENT 'Of those, swings (including fouls and balls in play).';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `whiffs` COMMENT 'Of those, swings and misses.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `velo_sum` COMMENT 'Sum of release speed (mph) over the pitches with one.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `velo_n` COMMENT 'Pitches with a release speed.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `spin_sum` COMMENT 'Sum of release spin rate (rpm) over the pitches with one.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `spin_n` COMMENT 'Pitches with a spin rate.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `woba_value` COMMENT 'Sum of wOBA values of the PAs that ended on this pitch type.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `xwoba_value` COMMENT 'Sum of xwOBA values of the same PAs.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `woba_den` COMMENT 'Those PAs (the wOBA denominator).';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `league_code` COMMENT 'Always MLB.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `source` COMMENT 'Always mlb_statcast.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.feature_pitch_daily ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.feature_contact_daily IS 'Each MLB batter\'s wOBA and Statcast expected wOBA (xwOBA) sums per day, with balls in play and their BABIP hits, from silver Statcast. wOBA - xwOBA over a span is how far his results ran ahead of (or behind) his contact quality; feeds the luck_gap insight detector. Grain: one row per batter per dt. Sources: mlb_statcast. Caveat: Written by the statcast_features_publish stage (in the nightly), from silver, not by gold_publish. Caveat: Statcast\'s wOBA weights, not gold\'s (feature_batter_daily); the two differ slightly. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `player_id` COMMENT 'FK to dim_player (the batter).';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `woba_value` COMMENT 'Sum of Savant woba_value over his PAs.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `xwoba_value` COMMENT 'Sum of xwOBA over the same PAs (balls in play by exit velocity and launch angle).';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `woba_den` COMMENT 'Those PAs (Savant woba_denom).';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `xwoba_bip_n` COMMENT 'Balls in play with an xwOBA estimate.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `bip` COMMENT 'Balls in play, not counting home runs (BABIP\'s denominator).';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `babip_hits` COMMENT 'Of those, hits.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `league_code` COMMENT 'Always MLB.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `source` COMMENT 'Always mlb_statcast.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.feature_contact_daily ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.insight_candidates IS 'Patterns in the season to date that are worth writing about, found by deterministic detectors (src/gbdp/insights/detectors.py, thresholds in configs/insights.yaml) as of dt: active hitting streaks, a batter\'s last 14 days against his own season, a league\'s month against its previous month, and MLB against NPB. Each row carries its numbers, sample size, a score and evidence_sql, a query over gold that re-derives the headline number. An LLM writing about one should state only these numbers and can re-run evidence_sql to check them. Grain: up to top_per_detector rows per detector per dt. Sources: feature_batter_daily, feature_pitch_daily, feature_contact_daily, dim_player. Caveat: {"Written by the insights_publish stage (in the nightly) for each window\'s end date, not by gold_publish for every dt": \'a dt is the as-of date of one run.\'} Caveat: change_vs_baseline is mostly regression to the mean (see the breakout model in the README); its score is a z-score against sampling noise, not a forecast. Caveat: Box-s...';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `insight_id` COMMENT 'Hash of detector, dt, league, subject and metric.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `detector` COMMENT 'hitting_streak, change_vs_baseline, league_month_shift, cross_league_gap, luck_gap, new_pitch or velocity_change.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `league_code` COMMENT 'MLB or NPB; for cross_league_gap the pair, e.g. MLB-NPB.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `subject_type` COMMENT 'player, league or league_pair.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `subject_id` COMMENT 'dim_player.player_id for a player; the league code(s) otherwise.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `subject_name` COMMENT 'dim_player.primary_name for a player (from its newest snapshot); the league code(s) otherwise.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `metric` COMMENT 'What value measures (hitting_streak_games, woba, k_rate, bb_rate, hr_rate, woba_minus_xwoba, pitch_share:<type>, velo:<type>).';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `value` COMMENT 'The headline number (the streak length, the recent or this-month rate, the first league\'s rate).';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `baseline` COMMENT 'What value is compared with (the season-before-window or previous-month rate, the second league\'s rate); null for streaks.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `delta` COMMENT 'value - baseline; null for streaks.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `sample_size` COMMENT 'PAs (or games, for a streak) behind value.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `score` COMMENT 'Strength within its detector, bigger is stronger (games for a streak, |z| otherwise).';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `rank` COMMENT '1 = highest score within its detector on dt.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `facts_json` COMMENT 'The detector\'s other numbers (dates, PAs, z, direction, caveat) as JSON.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `evidence_sql` COMMENT 'SQL over gold ({{table:...}} placeholders, as in this file) that re-derives the headline number.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `definition_version` COMMENT 'configs/insights.yaml definition_version.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `dt` COMMENT 'The as-of date.';

ALTER TABLE gbdp.gold_gbdp.insight_candidates ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.feature_batter_daily IS 'Each batter\'s counting stats on dt from fact_plate_appearance (the sources in configs/ml.yaml: MLB Statcast and NPB SPAIA). The daily building block of the breakout windows; summing a dt range of it gives that range\'s line. Grain: one row per (player_id, league_code) per dt, for batters with at least one PA. Sources: fact_plate_appearance. Caveat: wOBA terms use one fixed set of weights (configs/ml.yaml) for every league and season, and count intentional walks as walks (the feeds don\'t separate them). Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `player_id` COMMENT 'FK to dim_player (fact_plate_appearance.batter_id).';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `league_code` COMMENT 'MLB or NPB.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `source` COMMENT 'mlb_statcast or npb_spaia.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `pa` COMMENT 'Plate appearances (TRUNCATED rows excluded).';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `ab` COMMENT 'At-bats (vocabularies.event_type.groups.at_bat).';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `h` COMMENT 'Hits.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `doubles` COMMENT 'Doubles.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `triples` COMMENT 'Triples.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `hr` COMMENT 'Home runs.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `bb` COMMENT 'Walks.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `hbp` COMMENT 'Hit by pitch.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `so` COMMENT 'Strikeouts.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `sf` COMMENT 'Sacrifice flies.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `sh` COMMENT 'Sacrifice bunts.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `woba_den` COMMENT 'wOBA denominator, AB + BB + HBP + SF.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `woba_value` COMMENT 'wOBA numerator, the sum of the weights of his BB, HBP, 1B, 2B, 3B and HR.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `dt` COMMENT 'Game date.';

ALTER TABLE gbdp.gold_gbdp.feature_batter_daily ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.ml_split IS 'The train / validation / test split of each published dt, by date range (configs/ml.yaml splits), with the cut dates that produced it. Join on dt to split any dt-partitioned table without copying it; v_re_training does this for run expectancy. One row for every dt gold has published, with or without games, so it is also the record of which dates exist: a breakout label is filled only when every day of its window is here. Grain: one row per dt. Sources: configs/ml.yaml. Caveat: Written with the config of the publish that wrote it. If the cut dates move, split_version changes; re-publish to restamp older dates. Semantic layer: configs/semantic_layer.yaml.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `split` COMMENT 'train (dt <= train_end), validation (dt <= validation_end) or test. For run-expectancy rows, which look at nothing past their own inning.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `breakout_split` COMMENT 'As split, except embargo for as-of dates within embargo_days before a cut, whose breakout label window would reach into the next split.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `train_end` COMMENT 'Last train date.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `validation_end` COMMENT 'Last validation date.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `embargo_days` COMMENT 'Days before each cut that are embargo for breakout rows (= label_days).';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `split_version` COMMENT 'splits.name plus a hash of the split settings.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `dt` COMMENT 'The date.';

ALTER TABLE gbdp.gold_gbdp.ml_split ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

COMMENT ON TABLE gbdp.gold_gbdp.ml_breakout_examples IS 'Breakout prediction training data: one row per batter per as-of dt with features from the days up to and including dt and a label from the days strictly after it. A breakout is wOBA over the label_days days after dt at least margin_woba (0.050) above wOBA over the baseline_days days ending dt, with at least min_label_pa PAs after (configs/ml.yaml: 30-day baseline, 7-day recent window, 14-day label window, 50 and 30 PAs). Train on label_status = labeled rows, split by split. Grain: one row per (player_id, league_code) per as-of dt, for batters with at least min_baseline_pa PAs in the baseline window. Sources: feature_batter_daily, ml_split. Caveat: No leakage: features read feature_batter_daily for dt - baseline_days + 1 .. dt only, labels for dt + 1 .. dt + label_days only (tests/test_ml_breakout.py). Caveat: The label is null (pending) until every day of its window is in ml_split, i.e. published; gold fills it while publishing the window\'s last day. The newest label_days as-of dates are always pending. Ca...';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `player_id` COMMENT 'FK to dim_player.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `league_code` COMMENT 'MLB or NPB.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `season_year` COMMENT 'The as-of dt\'s calendar year.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_pa` COMMENT 'PAs in the baseline window (the baseline_days days ending dt).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_woba` COMMENT 'wOBA in the baseline window (feature_batter_daily woba_value / woba_den).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_k_rate` COMMENT 'Strikeouts per PA in the baseline window.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_bb_rate` COMMENT 'Walks per PA in the baseline window.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_iso` COMMENT 'Isolated power in the baseline window, (2B + 2*3B + 3*HR) / AB.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_babip` COMMENT 'BABIP in the baseline window, (H - HR) / (AB - SO - HR + SF); null with no balls in play.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_days` COMMENT 'Days with a PA in the baseline window.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_recent_pa` COMMENT 'PAs in the recent window (the recent_days days ending dt).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_recent_woba` COMMENT 'wOBA in the recent window; null without a wOBA PA.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_league_base_woba` COMMENT 'wOBA of every PA of his league in the baseline window.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_base_woba_vs_league` COMMENT 'f_base_woba - f_league_base_woba.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_day_pa` COMMENT 'PAs on dt.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_day_ab` COMMENT 'At-bats on dt.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_day_h` COMMENT 'Hits on dt.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `f_day_hr` COMMENT 'Home runs on dt.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `baseline_days` COMMENT 'Baseline window length the row was built with.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `recent_days` COMMENT 'Recent window length.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_days` COMMENT 'Label window length.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_status` COMMENT 'labeled, insufficient_pa (window complete, fewer than min_label_pa PAs; label_breakout null) or pending (window not yet fully published; every label column null).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_window_end` COMMENT 'Last day of the label window, dt + label_days.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_pa` COMMENT 'PAs in the label window (null while pending).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_woba` COMMENT 'wOBA in the label window (null while pending or with no wOBA PA).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_woba_delta` COMMENT 'label_woba - f_base_woba.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `label_breakout` COMMENT 'True when label_woba_delta >= margin_woba; null unless label_status = labeled.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `split` COMMENT 'train, validation, test or embargo (ml_split.breakout_split of the as-of dt).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `split_version` COMMENT 'The split settings the row was stamped with (ml_split.split_version).';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `definition_version` COMMENT 'Hash of configs/ml.yaml\'s breakout settings; rows from another definition are not comparable.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `dt` COMMENT 'As-of date.';

ALTER TABLE gbdp.gold_gbdp.ml_breakout_examples ALTER COLUMN `ingested_at_utc` COMMENT 'When this row was written.';

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_player_current
COMMENT 'Current version of every player in the latest dim_player snapshot (the newest dt only; a player missing from it is not current, whatever older snapshots say). One row per player_id.'
AS
SELECT player_id, primary_name, bats, throws, primary_position, league_id
FROM (
  SELECT p.player_id, p.primary_name, p.bats, p.throws, p.primary_position, p.league_id, p.dt,
         MAX(p.dt) OVER () AS latest_dt,
         ROW_NUMBER() OVER (PARTITION BY p.player_id ORDER BY p.dt DESC, p.valid_from_dt DESC) AS rn
  FROM gbdp.gold_gbdp.dim_player p
  WHERE p.is_current
) ranked
-- Only entities in the newest snapshot. (A join to MAX(dt), or a
-- scalar subquery, hits a DuckDB 1.5 binder error once joined.)
WHERE rn = 1 AND dt = latest_dt;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_team_current
COMMENT 'Current version of every team in the latest dim_team snapshot (the newest dt only). One row per team_id.'
AS
SELECT team_id, team_name, team_abbrev, home_city, league_id
FROM (
  SELECT t.team_id, t.team_name, t.team_abbrev, t.home_city, t.league_id, t.dt,
         MAX(t.dt) OVER () AS latest_dt,
         ROW_NUMBER() OVER (PARTITION BY t.team_id ORDER BY t.dt DESC, t.valid_from_dt DESC) AS rn
  FROM gbdp.gold_gbdp.dim_team t
  WHERE t.is_current
) ranked
-- Only entities in the newest snapshot. (A join to MAX(dt), or a
-- scalar subquery, hits a DuckDB 1.5 binder error once joined.)
WHERE rn = 1 AND dt = latest_dt;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_plate_appearance
COMMENT 'fact_plate_appearance with league, season, outcome flags (is_pa, is_ab, is_hit, ...; TRUNCATED rows have is_pa = 0 and every outcome flag 0) and RE24 run value: run expectancy after minus before, plus runs scored, using the league\'s full-season matrix, summed here from run_expectancy_daily (so it stays right when an earlier date is rebuilt and run_expectancy\'s later dates go stale).'
AS
WITH re AS (
  SELECT league_code, season_year, base_state, outs,
         CAST(SUM(runs) AS DOUBLE) / NULLIF(SUM(pa_count), 0) AS exp_runs
  FROM gbdp.gold_gbdp.run_expectancy_daily
  GROUP BY league_code, season_year, base_state, outs
),
pa AS (
  SELECT
    f.pa_id, f.game_id, f.dt,
    CAST(f.dt AS DATE) AS game_date,
    YEAR(CAST(f.dt AS DATE)) AS season_year,
    CASE f.source WHEN 'mlb_statsapi' THEN 'MLB' WHEN 'mlb_statcast' THEN 'MLB' WHEN 'retrosheet_local' THEN 'MLB' WHEN 'npb_spaia' THEN 'NPB' WHEN 'kbo_api' THEN 'KBO' WHEN 'kbo_local' THEN 'KBO' WHEN 'lmb_local' THEN 'LMB' WHEN 'indy_local' THEN 'INDY' END AS league_code,
    f.source AS data_source,
    f.inning, f.is_top_inning, f.batting_team_id, f.fielding_team_id, f.batter_id, f.pitcher_id,
    f.event_type, f.runs_scored_on_play, f.outs_on_play,
    f.base_state_before, f.outs_before, f.base_state_after, f.outs_after, f.runs_to_end_of_inning,
    CASE WHEN f.event_type IN ('TRUNCATED') THEN 0 ELSE 1 END AS is_pa,
    CASE WHEN f.event_type IN ('1B', '2B', '3B', 'HR', 'K', 'OUT', 'DP', 'TP', 'FC', 'ERROR') THEN 1 ELSE 0 END AS is_ab,
    CASE WHEN f.event_type IN ('1B', '2B', '3B', 'HR') THEN 1 ELSE 0 END AS is_hit,
    CASE WHEN f.event_type = '1B' THEN 1 ELSE 0 END AS is_single,
    CASE WHEN f.event_type = '2B' THEN 1 ELSE 0 END AS is_double,
    CASE WHEN f.event_type = '3B' THEN 1 ELSE 0 END AS is_triple,
    CASE WHEN f.event_type = 'HR' THEN 1 ELSE 0 END AS is_hr,
    CASE WHEN f.event_type IN ('BB') THEN 1 ELSE 0 END AS is_bb,
    CASE WHEN f.event_type IN ('HBP') THEN 1 ELSE 0 END AS is_hbp,
    CASE WHEN f.event_type IN ('K') THEN 1 ELSE 0 END AS is_k,
    CASE WHEN f.event_type IN ('SF', 'SH') THEN 1 ELSE 0 END AS is_sac,
    CASE WHEN f.event_type IN ('SF') THEN 1 ELSE 0 END AS is_sf,
    CASE WHEN f.event_type IN ('SH') THEN 1 ELSE 0 END AS is_sh,
    CASE f.event_type WHEN '1B' THEN 1 WHEN '2B' THEN 2 WHEN '3B' THEN 3 WHEN 'HR' THEN 4 ELSE 0 END AS total_bases
  FROM gbdp.gold_gbdp.fact_plate_appearance f
)
SELECT
  pa.*,
  before_state.exp_runs AS re_before,
  CASE WHEN pa.outs_after >= 3 THEN CAST(0 AS DOUBLE) ELSE after_state.exp_runs END AS re_after,
  CASE WHEN pa.outs_after >= 3 THEN CAST(0 AS DOUBLE) ELSE after_state.exp_runs END
    - before_state.exp_runs + pa.runs_scored_on_play AS run_value
FROM pa
LEFT JOIN re before_state
  ON before_state.league_code = pa.league_code AND before_state.season_year = pa.season_year
 AND before_state.base_state = pa.base_state_before AND before_state.outs = pa.outs_before
LEFT JOIN re after_state
  ON after_state.league_code = pa.league_code AND after_state.season_year = pa.season_year
 AND after_state.base_state = pa.base_state_after AND after_state.outs = pa.outs_after;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_batting_line
COMMENT 'fact_boxscore_batting with league and season, and 2b/3b as doubles/triples (the same name in every engine).'
AS
SELECT
  b.game_id, b.team_id, b.player_id, b.dt,
  CAST(b.dt AS DATE) AS game_date,
  YEAR(CAST(b.dt AS DATE)) AS season_year,
  CASE b.source WHEN 'mlb_statsapi' THEN 'MLB' WHEN 'mlb_statcast' THEN 'MLB' WHEN 'retrosheet_local' THEN 'MLB' WHEN 'npb_spaia' THEN 'NPB' WHEN 'kbo_api' THEN 'KBO' WHEN 'kbo_local' THEN 'KBO' WHEN 'lmb_local' THEN 'LMB' WHEN 'indy_local' THEN 'INDY' END AS league_code,
  b.source AS data_source,
  b.ab, b.h, b.c_2b AS doubles, b.c_3b AS triples, b.hr, b.bb, b.so, b.rbi, b.r
FROM gbdp.gold_gbdp.fact_boxscore_batting b;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_pitching_line
COMMENT 'fact_boxscore_pitching with league, season and ip_outs: innings pitched converted to outs. "6.1" is 19 outs, "6.2" is 20, kbo_api\'s "5 2/3" is 17 and "1/3" is 1. ip_outs is null when ip doesn\'t parse.'
AS
SELECT
  p.game_id, p.team_id, p.player_id, p.dt,
  CAST(p.dt AS DATE) AS game_date,
  YEAR(CAST(p.dt AS DATE)) AS season_year,
  CASE p.source WHEN 'mlb_statsapi' THEN 'MLB' WHEN 'mlb_statcast' THEN 'MLB' WHEN 'retrosheet_local' THEN 'MLB' WHEN 'npb_spaia' THEN 'NPB' WHEN 'kbo_api' THEN 'KBO' WHEN 'kbo_local' THEN 'KBO' WHEN 'lmb_local' THEN 'LMB' WHEN 'indy_local' THEN 'INDY' END AS league_code,
  p.source AS data_source,
  p.ip,
  CASE
    WHEN p.ip LIKE '%/3' THEN
      COALESCE(TRY_CAST(regexp_extract(p.ip, '^([0-9]+) ', 1) AS INT), 0) * 3
      + TRY_CAST(regexp_extract(p.ip, '([12])/3$', 1) AS INT)
    ELSE
      TRY_CAST(regexp_extract(p.ip, '^([0-9]+)', 1) AS INT) * 3
      + COALESCE(TRY_CAST(regexp_extract(p.ip, '[.]([0-2])$', 1) AS INT), 0)
  END AS ip_outs,
  p.h, p.r, p.er, p.bb, p.so, p.hr
FROM gbdp.gold_gbdp.fact_boxscore_pitching p;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_team_game
COMMENT 'One row per team per finished game: two per game (home and away). A game listed in several dts is kept once, on the first dt it was final. Games without both scores or not final (vocabularies.final_status) are left out. season_phase comes from game_type (vocabularies.season_phase).'
AS
WITH ranked AS (
  SELECT g.game_id, g.dt, g.source, g.game_type, g.home_team_id, g.away_team_id, g.home_score, g.away_score,
         ROW_NUMBER() OVER (PARTITION BY g.game_id ORDER BY g.dt) AS rn
  FROM gbdp.gold_gbdp.fact_game g
  WHERE (g.status IN ('Final', 'final', 'Game Over', 'Completed Early', '試合終了') OR g.status LIKE 'Final:%' OR g.status LIKE 'Completed Early:%') AND g.home_score IS NOT NULL AND g.away_score IS NOT NULL
),
games AS (
  SELECT game_id, dt, source, game_type, home_team_id, away_team_id, home_score, away_score
  FROM ranked
  WHERE rn = 1
),
sides AS (
  SELECT game_id, dt, source, game_type, home_team_id AS team_id, away_team_id AS opponent_team_id,
         1 AS is_home, home_score AS runs_scored, away_score AS runs_allowed
  FROM games
  UNION ALL
  SELECT game_id, dt, source, game_type, away_team_id AS team_id, home_team_id AS opponent_team_id,
         0 AS is_home, away_score AS runs_scored, home_score AS runs_allowed
  FROM games
)
SELECT
  game_id, dt,
  CAST(dt AS DATE) AS game_date,
  YEAR(CAST(dt AS DATE)) AS season_year,
  CASE source WHEN 'mlb_statsapi' THEN 'MLB' WHEN 'mlb_statcast' THEN 'MLB' WHEN 'retrosheet_local' THEN 'MLB' WHEN 'npb_spaia' THEN 'NPB' WHEN 'kbo_api' THEN 'KBO' WHEN 'kbo_local' THEN 'KBO' WHEN 'lmb_local' THEN 'LMB' WHEN 'indy_local' THEN 'INDY' END AS league_code,
  source AS data_source,
  game_type,
  CASE WHEN game_type IS NULL THEN 'unknown' WHEN source = 'mlb_statsapi' AND (game_type IN ('R')) THEN 'regular' WHEN source = 'mlb_statsapi' AND (game_type IN ('F', 'D', 'L', 'W')) THEN 'postseason' WHEN source = 'mlb_statsapi' AND (game_type IN ('A')) THEN 'allstar' WHEN source = 'mlb_statsapi' AND (game_type IN ('S')) THEN 'preseason' WHEN source = 'mlb_statsapi' AND (game_type IN ('E')) THEN 'exhibition' WHEN source = 'retrosheet_local' AND (game_type IN ('R')) THEN 'regular' WHEN source = 'retrosheet_local' AND (game_type IN ('F', 'D', 'L', 'W', 'P')) THEN 'postseason' WHEN source = 'retrosheet_local' AND (game_type IN ('A')) THEN 'allstar' WHEN source = 'retrosheet_local' AND (game_type IN ('E')) THEN 'exhibition' WHEN source = 'kbo_api' AND (game_type IN ('R')) THEN 'regular' WHEN source = 'kbo_api' AND (game_type IN ('P')) THEN 'postseason' WHEN source = 'kbo_api' AND (game_type IN ('A')) THEN 'allstar' WHEN source = 'kbo_api' AND (game_type IN ('E')) THEN 'exhibition' WHEN source = 'npb_spaia' AND (game_type IN ('セ・パ交流戦') OR game_type LIKE '%公式戦') THEN 'regular' WHEN source = 'npb_spaia' AND (game_type LIKE '%クライマックスシリーズ%' OR game_type LIKE '%日本シリーズ%') THEN 'postseason' WHEN source = 'npb_spaia' AND (game_type LIKE '%オールスター%') THEN 'allstar' WHEN source = 'npb_spaia' AND (game_type LIKE '%オープン戦%') THEN 'preseason' ELSE 'other' END AS season_phase,
  team_id, opponent_team_id, is_home, runs_scored, runs_allowed,
  CASE WHEN runs_scored > runs_allowed THEN 1 ELSE 0 END AS is_win,
  CASE WHEN runs_scored < runs_allowed THEN 1 ELSE 0 END AS is_loss,
  CASE WHEN runs_scored = runs_allowed THEN 1 ELSE 0 END AS is_tie
FROM sides;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_pitch
COMMENT 'fact_pitch with season, swing and whiff flags (vocabularies.pitch_result), and the batting and fielding team from the pitch\'s plate appearance.'
AS
WITH pa AS (
  SELECT pa_id, batting_team_id, fielding_team_id
  FROM (
    SELECT f.pa_id, f.batting_team_id, f.fielding_team_id,
           ROW_NUMBER() OVER (PARTITION BY f.pa_id ORDER BY f.dt DESC) AS rn
    FROM gbdp.gold_gbdp.fact_plate_appearance f
  ) ranked
  WHERE rn = 1
)
SELECT
  p.pitch_id, p.game_id, p.pa_id, p.dt,
  CAST(p.dt AS DATE) AS game_date,
  YEAR(CAST(p.dt AS DATE)) AS season_year,
  CASE p.source WHEN 'mlb_statsapi' THEN 'MLB' WHEN 'mlb_statcast' THEN 'MLB' WHEN 'retrosheet_local' THEN 'MLB' WHEN 'npb_spaia' THEN 'NPB' WHEN 'kbo_api' THEN 'KBO' WHEN 'kbo_local' THEN 'KBO' WHEN 'lmb_local' THEN 'LMB' WHEN 'indy_local' THEN 'INDY' END AS league_code,
  p.source AS data_source,
  p.pitcher_id, p.batter_id, pa.fielding_team_id AS pitching_team_id, pa.batting_team_id,
  p.pitch_number_in_pa, p.balls_before, p.strikes_before,
  NULLIF(p.pitch_type, '') AS pitch_type,
  p.release_speed, p.plate_x, p.plate_z, p.result,
  CASE WHEN p.result IN ('swinging_strike', 'swinging_strike_blocked', 'missed_bunt', 'foul', 'foul_tip', 'foul_bunt', 'bunt_foul_tip', 'hit_into_play', 'hit_into_play_no_out', 'hit_into_play_score') THEN 1 ELSE 0 END AS is_swing,
  CASE WHEN p.result IN ('swinging_strike', 'swinging_strike_blocked', 'missed_bunt') THEN 1 ELSE 0 END AS is_whiff
FROM gbdp.gold_gbdp.fact_pitch p
LEFT JOIN pa ON pa.pa_id = p.pa_id;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_run_expectancy_daily
COMMENT 'run_expectancy_daily with a date column and a readable base-state label.'
AS
SELECT
  r.league_code, r.season_year, r.base_state, r.outs, r.pa_count, r.runs, r.dt,
  CAST(r.dt AS DATE) AS game_date,
  CASE r.base_state WHEN 0 THEN 'Bases empty' WHEN 1 THEN '1st' WHEN 2 THEN '2nd' WHEN 3 THEN '1st & 2nd' WHEN 4 THEN '3rd' WHEN 5 THEN '1st & 3rd' WHEN 6 THEN '2nd & 3rd' WHEN 7 THEN 'Loaded' ELSE CAST(r.base_state AS STRING) END AS runners
FROM gbdp.gold_gbdp.run_expectancy_daily r;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.v_re_training
COMMENT 'Run-expectancy training rows: every plate appearance with a known base state, outs (0-2) and runs_to_end_of_inning (the target), with its league and its date\'s train / validation / test split from ml_split. The same rows run_expectancy_daily counts; no data is copied.'
AS
SELECT
  f.pa_id, f.game_id, f.dt,
  CAST(f.dt AS DATE) AS game_date,
  YEAR(CAST(f.dt AS DATE)) AS season_year,
  CASE f.source WHEN 'mlb_statsapi' THEN 'MLB' WHEN 'mlb_statcast' THEN 'MLB' WHEN 'retrosheet_local' THEN 'MLB' WHEN 'npb_spaia' THEN 'NPB' WHEN 'kbo_api' THEN 'KBO' WHEN 'kbo_local' THEN 'KBO' WHEN 'lmb_local' THEN 'LMB' WHEN 'indy_local' THEN 'INDY' END AS league_code,
  f.source AS data_source,
  f.inning, f.is_top_inning, f.event_type,
  f.base_state_before, f.outs_before, f.runs_to_end_of_inning,
  s.split, s.split_version
FROM gbdp.gold_gbdp.fact_plate_appearance f
JOIN gbdp.gold_gbdp.ml_split s ON s.dt = f.dt
WHERE f.runs_to_end_of_inning IS NOT NULL
  AND f.base_state_before IS NOT NULL
  AND f.outs_before BETWEEN 0 AND 2;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.mv_batting
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Batting from plate appearances (MLB Statcast, NPB, Retrosheet), with RE24. Defined in configs/semantic_layer.yaml.
source: gbdp.gold_gbdp.v_plate_appearance
joins:
- name: batter
  source: gbdp.gold_gbdp.v_player_current
  'on': source.batter_id = batter.player_id
- name: pitcher
  source: gbdp.gold_gbdp.v_player_current
  'on': source.pitcher_id = pitcher.player_id
- name: batting_team
  source: gbdp.gold_gbdp.v_team_current
  'on': source.batting_team_id = batting_team.team_id
dimensions:
- name: batter_id
  expr: source.batter_id
  comment: Batter's player_id.
- name: batter_name
  expr: batter.primary_name
  comment: Batter's current name.
- name: pitcher_id
  expr: source.pitcher_id
  comment: Pitcher's player_id (null for NPB).
- name: pitcher_name
  expr: pitcher.primary_name
  comment: Pitcher's current name.
- name: team_id
  expr: source.batting_team_id
  comment: The batting team.
- name: team_name
  expr: batting_team.team_name
  comment: The batting team's current name.
- name: league_code
  expr: source.league_code
  comment: MLB or NPB.
- name: season_year
  expr: source.season_year
  comment: Calendar year of the game.
- name: game_date
  expr: source.game_date
  comment: Game date.
- name: data_source
  expr: source.data_source
  comment: 'Source system: mlb_statcast, npb_spaia or retrosheet_local.'
- name: event_type
  expr: source.event_type
  comment: Outcome code, see vocabularies.event_type.
- name: base_state_before
  expr: source.base_state_before
  comment: Runners before the PA (bitmask).
- name: outs_before
  expr: source.outs_before
  comment: Outs before the PA.
- name: inning
  expr: source.inning
  comment: Inning.
measures:
- name: pa
  expr: SUM(source.is_pa)
  comment: 'Plate appearances. Caveats: TRUNCATED rows are not plate appearances and are excluded.'
- name: ab
  expr: SUM(source.is_ab)
  comment: At-bats (1B, 2B, 3B, HR, K, OUT, DP, TP, FC, ERROR).
- name: hits
  expr: SUM(source.is_hit)
  comment: Hits.
- name: doubles
  expr: SUM(source.is_double)
  comment: Doubles.
- name: triples
  expr: SUM(source.is_triple)
  comment: Triples.
- name: home_runs
  expr: SUM(source.is_hr)
  comment: Home runs.
- name: walks
  expr: SUM(source.is_bb)
  comment: Walks, intentional included.
- name: hit_by_pitch
  expr: SUM(source.is_hbp)
  comment: Times hit by a pitch.
- name: strikeouts
  expr: SUM(source.is_k)
  comment: Strikeouts.
- name: sac_flies
  expr: SUM(source.is_sf)
  comment: Sacrifice flies (SF).
- name: sac_bunts
  expr: SUM(source.is_sh)
  comment: Sacrifice bunts (SH).
- name: total_bases
  expr: SUM(source.total_bases)
  comment: Total bases (1B = 1, 2B = 2, 3B = 3, HR = 4).
- name: avg
  expr: SUM(source.is_hit) / NULLIF(SUM(source.is_ab), 0)
  comment: 'Batting average, hits / at-bats. Caveats: Until the gold rebuild, a sacrifice fly double play written before the SF/SH split is DP and so counts as an at-bat, though officially it isn''t one.'
- name: obp
  expr: (SUM(source.is_hit) + SUM(source.is_bb) + SUM(source.is_hbp)) / NULLIF(SUM(source.is_ab) + SUM(source.is_bb) + SUM(source.is_hbp) + SUM(source.is_sf), 0)
  comment: On-base percentage, (H + BB + HBP) / (AB + BB + HBP + SF). Sacrifice bunts are left out, as officially.
- name: slg
  expr: SUM(source.total_bases) / NULLIF(SUM(source.is_ab), 0)
  comment: 'Slugging percentage, total bases / at-bats. Caveats: Until the gold rebuild, a sacrifice fly double play written before the SF/SH split is DP and so counts as an at-bat, though officially it isn''t one.'
- name: ops
  expr: (SUM(source.is_hit) + SUM(source.is_bb) + SUM(source.is_hbp)) / NULLIF(SUM(source.is_ab) + SUM(source.is_bb) + SUM(source.is_hbp) + SUM(source.is_sf), 0) + SUM(source.total_bases) / NULLIF(SUM(source.is_ab), 0)
  comment: 'On-base plus slugging, OBP + SLG. Caveats: Inherits the OBP sacrifice caveat.'
- name: bb_pct
  expr: SUM(source.is_bb) / NULLIF(SUM(source.is_pa), 0)
  comment: Walk rate, walks / plate appearances (a share, 0-1).
- name: k_pct
  expr: SUM(source.is_k) / NULLIF(SUM(source.is_pa), 0)
  comment: Strikeout rate, strikeouts / plate appearances (a share, 0-1).
- name: runs_on_play
  expr: SUM(source.runs_scored_on_play)
  comment: 'Runs the batting team scored during these plate appearances, TRUNCATED rows included. Caveats: Not the batter''s runs or RBI. For MLB team totals per game it equals the final score when the feed is complete.'
- name: re24
  expr: SUM(source.run_value)
  comment: 'RE24 run value: the sum over plate appearances of (run expectancy after - run expectancy before + runs scored), with the league''s full-season matrix (summed from run_expectancy_daily). Positive means the batter added runs. Caveats: TRUNCATED rows count (they carry the inning''s last runs and outs), as do base-running events Statcast credits to the PA. PAs whose state after is unknown (a walk-off, NPB text without the runners) have no run value and are left out. The run expectancy matrix is the league''s whole season summed from run_expectancy_daily, so it covers only the dates loaded so far while the season is in progress, and a PA is valued against games played after it as well as before.'
$$;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.mv_batting_box
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Batting from box scores (MLB Stats API, KBO, local files). The only source of RBI and runs for MLB, and of any KBO batting. Defined in configs/semantic_layer.yaml.
source: gbdp.gold_gbdp.v_batting_line
joins:
- name: player
  source: gbdp.gold_gbdp.v_player_current
  'on': source.player_id = player.player_id
- name: team
  source: gbdp.gold_gbdp.v_team_current
  'on': source.team_id = team.team_id
dimensions:
- name: player_id
  expr: source.player_id
  comment: Batter's player_id.
- name: player_name
  expr: player.primary_name
  comment: Batter's current name.
- name: team_id
  expr: source.team_id
  comment: The batter's team.
- name: team_name
  expr: team.team_name
  comment: The team's current name.
- name: league_code
  expr: source.league_code
  comment: League code.
- name: season_year
  expr: source.season_year
  comment: Calendar year of the game.
- name: game_date
  expr: source.game_date
  comment: Game date.
- name: data_source
  expr: source.data_source
  comment: Source system.
measures:
- name: rbi
  expr: SUM(source.rbi)
  comment: Runs batted in.
- name: batter_runs
  expr: SUM(source.r)
  comment: Runs scored by the batter.
- name: box_games
  expr: COUNT(DISTINCT source.game_id)
  comment: Games with a box-score batting line.
- name: box_avg
  expr: SUM(source.h) / NULLIF(SUM(source.ab), 0)
  comment: Batting average from box scores, hits / at-bats. Use avg where plate appearances exist; this is for KBO and box-score-only data.
$$;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.mv_pitching
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Pitching from box scores (MLB Stats API, KBO, local files). Defined in configs/semantic_layer.yaml.
source: gbdp.gold_gbdp.v_pitching_line
joins:
- name: pitcher
  source: gbdp.gold_gbdp.v_player_current
  'on': source.player_id = pitcher.player_id
- name: team
  source: gbdp.gold_gbdp.v_team_current
  'on': source.team_id = team.team_id
dimensions:
- name: pitcher_id
  expr: source.player_id
  comment: Pitcher's player_id.
- name: pitcher_name
  expr: pitcher.primary_name
  comment: Pitcher's current name.
- name: team_id
  expr: source.team_id
  comment: The pitcher's team.
- name: team_name
  expr: team.team_name
  comment: The team's current name.
- name: league_code
  expr: source.league_code
  comment: League code.
- name: season_year
  expr: source.season_year
  comment: Calendar year of the game.
- name: game_date
  expr: source.game_date
  comment: Game date.
- name: data_source
  expr: source.data_source
  comment: Source system.
measures:
- name: outs_recorded
  expr: SUM(source.ip_outs)
  comment: Outs recorded (innings pitched x 3).
- name: ip
  expr: SUM(source.ip_outs) / 3.0
  comment: 'Innings pitched as a number, outs / 3 (6.1 innings = 6.333). Caveats: Summed as outs never as the "6.1" strings.'
- name: ip_display
  expr: concat(CAST(CAST(FLOOR(SUM(source.ip_outs) / 3) AS BIGINT) AS STRING), '.', CAST(CAST(SUM(source.ip_outs) % 3 AS BIGINT) AS STRING))
  comment: Innings pitched in baseball notation, whole innings and thirds ("6.1" = 6 1/3).
- name: games_pitched
  expr: COUNT(DISTINCT source.game_id)
  comment: Games with a pitching line.
- name: hits_allowed
  expr: SUM(source.h)
  comment: Hits allowed.
- name: earned_runs
  expr: SUM(source.er)
  comment: Earned runs allowed.
- name: pitcher_strikeouts
  expr: SUM(source.so)
  comment: Strikeouts by the pitcher.
- name: pitcher_walks
  expr: SUM(source.bb)
  comment: 'Walks allowed. Caveats: kbo_api counts walks plus hit batters.'
- name: era
  expr: 27.0 * SUM(source.er) / NULLIF(SUM(source.ip_outs), 0)
  comment: 'Earned run average, 9 x earned runs / innings pitched. Caveats: Lines whose ip doesn''t parse have no outs so their earned runs still count against zero innings. None do in the current data.'
- name: whip
  expr: 3.0 * (SUM(source.bb) + SUM(source.h)) / NULLIF(SUM(source.ip_outs), 0)
  comment: Walks plus hits per inning pitched.
- name: k_per_9
  expr: 27.0 * SUM(source.so) / NULLIF(SUM(source.ip_outs), 0)
  comment: Strikeouts per nine innings.
- name: bb_per_9
  expr: 27.0 * SUM(source.bb) / NULLIF(SUM(source.ip_outs), 0)
  comment: Walks per nine innings.
$$;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.mv_team_games
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: 'Team results from finished games in fact_game (every league with game scores). Filter season_phase for the part of the season you want: the API and MCP default to regular season (season_phase regular or unknown) when a request doesn''t filter season_phase; a Unity Catalog metric view can''t hold a default, so filter it yourself there. Defined in configs/semantic_layer.yaml.'
source: gbdp.gold_gbdp.v_team_game
joins:
- name: team
  source: gbdp.gold_gbdp.v_team_current
  'on': source.team_id = team.team_id
- name: opponent
  source: gbdp.gold_gbdp.v_team_current
  'on': source.opponent_team_id = opponent.team_id
dimensions:
- name: team_id
  expr: source.team_id
  comment: The team.
- name: team_name
  expr: team.team_name
  comment: The team's current name.
- name: team_abbrev
  expr: team.team_abbrev
  comment: The team's abbreviation (MLB only).
- name: opponent_team_id
  expr: source.opponent_team_id
  comment: The opponent.
- name: opponent_name
  expr: opponent.team_name
  comment: The opponent's current name.
- name: is_home
  expr: source.is_home
  comment: 1 for home games, 0 for away.
- name: season_phase
  expr: source.season_phase
  comment: regular, postseason, allstar, preseason, exhibition, other or unknown (vocabularies.season_phase). Filter to regular for a season record.
- name: game_type
  expr: source.game_type
  comment: The source's own game type code or name.
- name: league_code
  expr: source.league_code
  comment: League code.
- name: season_year
  expr: source.season_year
  comment: Calendar year of the game.
- name: game_date
  expr: source.game_date
  comment: Game date (first dt the game was final).
- name: data_source
  expr: source.data_source
  comment: Source system.
measures:
- name: games_played
  expr: COUNT(*)
  comment: 'Finished games. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: wins
  expr: SUM(source.is_win)
  comment: 'Wins. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: losses
  expr: SUM(source.is_loss)
  comment: 'Losses. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: ties
  expr: SUM(source.is_tie)
  comment: 'Ties (NPB plays them). Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: win_pct
  expr: SUM(source.is_win) / NULLIF(SUM(source.is_win) + SUM(source.is_loss), 0)
  comment: 'Winning percentage, wins / (wins + losses); ties don''t count, as in NPB standings. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: runs_scored
  expr: SUM(source.runs_scored)
  comment: 'Runs scored. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: runs_allowed
  expr: SUM(source.runs_allowed)
  comment: 'Runs allowed. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
- name: run_differential
  expr: SUM(source.runs_scored) - SUM(source.runs_allowed)
  comment: 'Runs scored minus runs allowed. Caveats: Regular season (and games whose type is unknown) by default in the API and MCP; filter season_phase in Unity Catalog. Games published before gold had game_type are unknown, postseason included.'
$$;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.mv_pitches
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Pitch tracking (MLB Statcast). Defined in configs/semantic_layer.yaml.
source: gbdp.gold_gbdp.v_pitch
joins:
- name: pitcher
  source: gbdp.gold_gbdp.v_player_current
  'on': source.pitcher_id = pitcher.player_id
- name: batter
  source: gbdp.gold_gbdp.v_player_current
  'on': source.batter_id = batter.player_id
- name: team
  source: gbdp.gold_gbdp.v_team_current
  'on': source.pitching_team_id = team.team_id
dimensions:
- name: pitcher_id
  expr: source.pitcher_id
  comment: Pitcher's player_id.
- name: pitcher_name
  expr: pitcher.primary_name
  comment: Pitcher's current name.
- name: batter_id
  expr: source.batter_id
  comment: Batter's player_id.
- name: batter_name
  expr: batter.primary_name
  comment: Batter's current name.
- name: team_id
  expr: source.pitching_team_id
  comment: The pitching (fielding) team.
- name: team_name
  expr: team.team_name
  comment: The pitching team's current name.
- name: league_code
  expr: source.league_code
  comment: Always MLB.
- name: season_year
  expr: source.season_year
  comment: Calendar year of the game.
- name: game_date
  expr: source.game_date
  comment: Game date.
- name: pitch_type
  expr: source.pitch_type
  comment: Statcast pitch type code.
- name: pitch_type_name
  expr: CASE source.pitch_type WHEN 'FF' THEN '4-seam fastball' WHEN 'SI' THEN 'Sinker' WHEN 'FC' THEN 'Cutter' WHEN 'SL' THEN 'Slider' WHEN 'ST' THEN 'Sweeper' WHEN 'SV' THEN 'Slurve' WHEN 'CU' THEN 'Curveball' WHEN 'KC' THEN 'Knuckle curve' WHEN 'CS' THEN 'Slow curve' WHEN 'CH' THEN 'Changeup' WHEN 'FS' THEN 'Splitter' WHEN 'FO' THEN 'Forkball' WHEN 'SC' THEN 'Screwball' WHEN 'KN' THEN 'Knuckleball' WHEN 'EP' THEN 'Eephus' WHEN 'FA' THEN 'Other fastball' WHEN 'PO' THEN 'Pitchout' ELSE CAST(source.pitch_type AS STRING) END
  comment: Pitch type name (code when unlisted).
- name: balls_before
  expr: source.balls_before
  comment: Balls in the count.
- name: strikes_before
  expr: source.strikes_before
  comment: Strikes in the count.
measures:
- name: pitches
  expr: COUNT(*)
  comment: Pitches thrown.
- name: avg_velocity
  expr: AVG(source.release_speed)
  comment: 'Average release speed, mph. Caveats: Compare within a pitch_type; a mix of pitch types averages fastballs with breaking balls.'
- name: max_velocity
  expr: MAX(source.release_speed)
  comment: Fastest release speed, mph.
- name: swings
  expr: SUM(source.is_swing)
  comment: Pitches swung at (vocabularies.pitch_result.swing).
- name: whiffs
  expr: SUM(source.is_whiff)
  comment: Swings and misses (vocabularies.pitch_result.whiff).
- name: whiff_rate
  expr: SUM(source.is_whiff) / NULLIF(SUM(source.is_swing), 0)
  comment: 'Whiffs / swings (a share, 0-1). Caveats: Foul tips are swings with contact not whiffs.'
$$;

CREATE OR REPLACE VIEW gbdp.gold_gbdp.mv_run_expectancy
WITH METRICS
LANGUAGE YAML
AS $$
version: 1.1
comment: Run expectancy matrix over any date range, summed from run_expectancy_daily. Defined in configs/semantic_layer.yaml.
source: gbdp.gold_gbdp.v_run_expectancy_daily
dimensions:
- name: league_code
  expr: source.league_code
  comment: MLB or NPB.
- name: season_year
  expr: source.season_year
  comment: Calendar year.
- name: game_date
  expr: source.game_date
  comment: Game date.
- name: base_state
  expr: source.base_state
  comment: Runners on base (bitmask).
- name: runners
  expr: source.runners
  comment: Runners on base, as text.
- name: outs
  expr: source.outs
  comment: Outs, 0-2.
measures:
- name: exp_runs
  expr: SUM(source.runs) / NULLIF(SUM(source.pa_count), 0)
  comment: 'Expected runs to the end of the half-inning from a base/out state, over the chosen dates. Caveats: Group by league_code base_state and outs; mixing states or leagues gives a meaningless average.'
- name: re_pa_count
  expr: SUM(source.pa_count)
  comment: Plate appearances behind the run expectancy (the sample size).
$$;
